from __future__ import annotations

import io
import os
import tokenize

root = os.path.dirname(os.path.abspath(__file__))
results: list[tuple[str, int]] = []

for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = sorted(d for d in dirnames if d not in {'.git', '__pycache__', '.venv', 'node_modules'})
    for filename in sorted(filenames):
        if not filename.endswith('.py'):
            continue
        full = os.path.join(dirpath, filename)
        rel = os.path.relpath(full, root).replace(os.sep, '/')
        if rel == '_scan_todos.py':
            continue
        with open(full, 'rb') as f:
            data = f.read()
        try:
            tokens = list(tokenize.tokenize(io.BytesIO(data).readline))
        except (tokenize.TokenError, IndentationError, SyntaxError):
            tokens = []
            try:
                for tok in tokenize.tokenize(io.BytesIO(data).readline):
                    tokens.append(tok)
            except Exception:
                pass
        for tok in tokens:
            if tok.type == tokenize.COMMENT and 'TODO' in tok.string:
                results.append((rel, tok.start[0]))

results.sort()
with open(os.path.join(root, 'todos.txt'), 'w', encoding='utf-8', newline='\n') as f:
    for rel, line in results:
        f.write(f'{rel}:{line}\n')

print(len(results))
for rel, line in results:
    print(f'{rel}:{line}')
os.remove(os.path.join(root, '_scan_todos.py'))
